function mailOpenSnooze(anchor: HTMLElement) {
  anchor.dispatchEvent(new CustomEvent("snooze-row", { bubbles: true }));
}

function Empty({ view, searching, category }: { view: Parameters<typeof emptyCopy>[0]; searching: boolean; category: Category }) {
  const copy = emptyCopy(view, searching, category);
  return (
    <div className="empty">
      <svg viewBox="0 0 120 80" width="120" height="80" aria-hidden="true">
        <rect x="8" y="16" width="104" height="56" rx="8" fill="none" stroke="currentColor" strokeWidth="2" />
        <path d="M10 20 60 48 110 20" fill="none" stroke="currentColor" strokeWidth="2" />
      </svg>
      <strong>{copy.title}</strong>
      <p>{copy.body}</p>
    </div>
  );
}

function SelectBox({
  checked,
  partial,
  onChange,
  label,
}: {
  checked: boolean;
  partial: boolean;
  onChange: () => void;
  label: string;
}) {
  const ref = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (ref.current) ref.current.indeterminate = partial;
  }, [partial, checked]);
  return <input ref={ref} type="checkbox" checked={checked} aria-label={label} onChange={onChange} />;
}

export function useRowSnooze() {
  const { openPalette, dispatch } = useMail();
  useEffect(() => {
    const on = (event: Event) => {
      const target = event.target as HTMLElement;
      openPalette("snooze", target);
    };
    document.addEventListener("snooze-row", on);
    return () => document.removeEventListener("snooze-row", on);
  }, [openPalette, dispatch]);
}

