        type="button"
        aria-label={thread.labels.includes(SYS.STARRED) ? "Unstar" : "Star"}
        onClick={(event) => {
          event.stopPropagation();
          dispatch({ type: "star", ids: [thread.id] });
        }}
      >
        <Icon name="star" size={18} />
      </button>
