    const on = (event: Event) => {
      const target = event.target as HTMLElement;
      openPalette("snooze", target);
    };
    document.addEventListener("snooze-row", on);
    return () => document.removeEventListener("snooze-row", on);
  }, [openPalette, dispatch]);
