      <span className="row-actions">
        <button className="icon-btn tiny" type="button" aria-label="Archive" onClick={(event) => { event.stopPropagation(); dispatch({ type: "archive", ids: [thread.id] }); }}>
          <Icon name="archive" size={18} />
