            event.stopPropagation();
            dispatch({ type: "read", ids: [thread.id], unread: !thread.unread });
          }}
        >
          <Icon name={thread.unread ? "mail" : "unread"} size={18} />
        </button>
        <button className="icon-btn tiny" type="button" aria-label="Snooze" onClick={(event) => { event.stopPropagation(); dispatch({ type: "cursor", id: thread.id }); mailOpenSnooze(event.currentTarget); }}>
          <Icon name="snooze" size={18} />
        </button>
      </span>
