                <form
                  className="link-pop"
                  onSubmit={(event) => {
                    event.preventDefault();
                    if (isEmail(linkUrl) || /^https?:\/\//i.test(linkUrl) || linkUrl.startsWith("mailto:")) command("createLink", linkUrl);
