                      <span>{preset.label}</span>
                      <small>{preset.hint}</small>
                    </button>
                  ))}
                </div>
              ) : null}
            </div>
            <div className="format-bar">
              <button type="button" aria-label="Bold" onMouseDown={(event) => event.preventDefault()} onClick={() => command("bold")}>
