function RecipientRow({
  label,
  people,
  text,
  setText,
  suggestions,
  onRemove,
  onPick,
  onCommit,
  trailing,
  testid,
  autoFocus,
}: {
  label: string;
  people: Person[];
  text: string;
  setText: (value: string) => void;
  suggestions: Person[];
  onRemove: (email: string) => void;
  onPick: (person: Person) => void;
  onCommit: () => void;
  trailing?: React.ReactNode;
  testid?: string;
  autoFocus?: boolean;
}) {
  const [open, setOpen] = useState(false);
  return (
    <div className="recipient-row">
      <span>{label}</span>
      <div className="recipient-box">
        {people.map((person) => (
          <span key={person.email} className="person-chip">
            <Avatar person={person} size={20} />
            {person.name}
            <button type="button" aria-label={`Remove ${person.name}`} onClick={() => onRemove(person.email)}>
              <Icon name="close" size={12} />
            </button>
          </span>
        ))}
        <input
          data-testid={testid}
          value={text}
          autoFocus={autoFocus}
          placeholder={people.length ? "" : "Recipients"}
          onChange={(event) => {
            setText(event.target.value);
            setOpen(true);
          }}
          onFocus={() => setOpen(true)}
          onBlur={() => {
            onCommit();
            window.setTimeout(() => setOpen(false), 120);
          }}
          onKeyDown={(event) => {
            if (event.key === "Enter" || event.key === "," || event.key === "Tab") {
              if (text.trim()) {
                event.preventDefault();
                onCommit();
              }
            } else if (event.key === "Backspace" && !text && people.length) {
              onRemove(people[people.length - 1].email);
            }
          }}
        />
        {open && text.trim() && suggestions.length ? (
          <div className="suggest recipient-suggest">
            {suggestions.map((person) => (
              <button
                key={person.email}
                type="button"
                onMouseDown={(event) => event.preventDefault()}
                onClick={() => onPick(person)}
              >
                <Avatar person={person} size={28} />
                <span>
                  <strong>{person.name}</strong>
                  <small>{person.email}</small>
                </span>
              </button>
            ))}
          </div>
        ) : null}
      </div>
      {trailing}
    </div>
  );
}

