    const body = sanitizeHtml(editorRef.current?.innerHTML || compose.body);
    const subject = compose.subject.trim();
    if (!subject && !askSubject) {
      setAskSubject(true);
      return;
    }
    skipSave.current = true;
    dispatch({
      type: "send",
      composeId: compose.id,
      input: {
