      data-testid={compose.placement === "float" ? "compose-window" : "compose-inline"}
      onDragOver={(event) => {
        event.preventDefault();
        setDragging(true);
      }}
      onDragLeave={() => setDragging(false)}
      onDrop={(event) => {
