    case "sign":
      return {
        ...state,
        signedIn: action.signedIn,
        accountOpen: false,
        settingsPage: false,
        quickSettings: false,
        openThreadId: null,
      };
    case "ui":
      return { ...state, ...action.patch };
    case "confirm":
      return { ...state, confirm: action.confirm };
    default: {
      const neverAction: never = action;
      return neverAction;
    }
  }
}

export function parseLocationHash(hash: string): Route {
  return parseHash(hash);
}

