    const onHash = () => dispatch({ type: "route", route: parseLocationHash(location.hash) });
    window.addEventListener("hashchange", onHash);
    return () => window.removeEventListener("hashchange", onHash);
  }, []);

  useEffect(() => {
    const current = location.hash || "#/inbox";
    if (current === hash) {
