      return;
    }
    const prevPath = prevHash.current.split("?")[0];
    const nextPath = hash.split("?")[0];
    prevHash.current = hash;
    if (prevPath === nextPath) history.replaceState(null, "", hash);
    else location.hash = hash;
  }, [hash]);

