.snack {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  background: var(--snack);
  color: white;
  min-height: 48px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 8px 0 16px;
  z-index: 80;
  box-shadow: var(--pop);
}
:root[data-theme="dark"] .snack { color: #1f1f1f; }
