              event.stopPropagation();
              setEditor({ id: label.id, name: label.name, color: 0 });
            }
          }}
        >
          <Icon name="pencil" size={14} />
        </span>
      </button>
    );
  })}
</div>
<LabelDialog
  editor={editor}
  onClose={() => setEditor(null)}

