  return (
    <section
      className={cx(
        "compose",
        compose.placement,
        compose.minimized && "min",
        compose.maximized && "max",
        dragging && "drag",
      )}
      style={compose.placement === "float" && !compose.maximized ? { right } : undefined}
      data-testid={compose.placement === "float" ? "compose-window" : "compose-inline"}
      onDragOver={(event) => {
