            role="textbox"
            aria-label="Message body"
            onInput={syncBody}
            onKeyDown={(event) => {
              if ((event.metaKey || event.ctrlKey) && event.key === "Enter") {
                event.preventDefault();
                send(null);
              }
            }}
          />
