  color: #041e49;
  font-size: 13px;
  text-align: left;
}
:root[data-theme="dark"] .banner, :root[data-theme="dark"] .sched-banner, :root[data-theme="dark"] .search-chip {
  background: #004a77;
  color: #d3e3fd;
}
.search-chip button, .sched-banner button {
  display: inline-flex;
