  border-radius: 12px;
  padding: 2px 8px;
  color: inherit;
}
.folder-line { padding: 2px 16px 6px; font-size: 13px; font-weight: 500; color: var(--muted); }
.star:not(.on), .imp:not(.on) { opacity: 0.45; }
.tabs {
