:root[data-theme="dark"] .tab-primary.on,
:root[data-theme="dark"] .tab-social.on { color: #a8c7fa; border-color: #a8c7fa; }
:root[data-theme="dark"] .tab-promotions.on { color: #81c995; border-color: #81c995; }
:root[data-theme="dark"] .tab-updates.on { color: #f9ab00; border-color: #f9ab00; }
.rows { overflow: auto; min-height: 0; flex: 1; }
.section-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 32px;
  padding: 0 16px;
  background: var(--bg);
  color: var(--secondary);
