  top: 0;
  z-index: 1;
}
.section-label em { font-style: normal; font-weight: 500; }
.row {
  position: relative;
  display: grid;
  grid-template-columns: 28px 28px 24px minmax(96px, 180px) minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 4px;
  height: var(--row-h);
  padding: 0 8px 0 8px;
  cursor: pointer;
  user-select: none;
}
.row.is-read { background: var(--row-read); color: var(--secondary); }
.row.is-unread { background: var(--row-unread); }
.row:hover { background: var(--row-hover); }
.row.is-selected, .row.is-selected:hover { background: var(--row-selected); }
.row.is-cursor { box-shadow: inset 3px 0 0 #0b57d0; }
.row.is-open { box-shadow: inset 3px 0 0 #0b57d0; }
.sender, .content, .subject, .snippet { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sender { font-size: 14px; }
.content { display: flex; align-items: center; gap: 6px; font-size: 14px; }
.subject { color: var(--text); }
.snippet { color: var(--muted); font-weight: 400; }
.strong { font-weight: 700; }
.chip {
