.row-actions {
  display: none;
  position: absolute;
  right: 4px;
  top: 0;
  bottom: 0;
  align-items: center;
  padding-left: 8px;
}
.row.is-read .row-actions { background: var(--row-read); }
.row.is-unread .row-actions { background: var(--row-unread); }
.row:hover .row-actions { display: flex; background: var(--row-hover); }
.row.is-selected .row-actions, .row.is-selected:hover .row-actions { background: var(--row-selected); }
.row:hover .when { visibility: hidden; }
.star.on { color: var(--star); opacity: 1; }
.imp.on { color: var(--important); opacity: 1; }
.row .imp:not(.on) { opacity: 0; }
.row:hover .imp:not(.on), .row.is-selected .imp:not(.on) { opacity: 0.55; }
.empty {
  height: 100%;
  min-height: 240px;
  display: grid;
