* { box-sizing: border-box; }
html, body, #root { height: 100%; }
body {
  margin: 0;
  overflow: hidden;
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}
button, input, textarea { font: inherit; color: inherit; }
button { background: none; border: 0; padding: 0; cursor: pointer; }
input, textarea { background: transparent; border: 0; }
a { color: var(--blue); }
:focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; }
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.app {
  height: 100dvh;
  display: grid;
  grid-template-rows: var(--top) minmax(0, 1fr);
  background: var(--bg);
}
.app[data-collapsed="true"] { --side: 72px; }
.app[data-density="compact"] { --row-h: 32px; }
.app[data-density="comfortable"] { --row-h: 52px; }

.topbar {
  display: grid;
  grid-template-columns: var(--side) minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding-right: 12px;
  height: var(--top);
}
.brand { display: flex; align-items: center; gap: 4px; padding-left: 8px; min-width: 0; }
.logo {
  margin: 0;
  font-size: 22px;
  font-weight: 400;
  letter-spacing: -0.2px;
  color: var(--logo);
  white-space: nowrap;
  line-height: 1;
}
.icon-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--icon);
  flex: none;
}
.icon-btn:hover { background: var(--hover); }
.icon-btn.tiny { width: 28px; height: 28px; }
.icon-btn:disabled { opacity: 0.38; cursor: default; }
.avatar-btn { width: 48px; height: 48px; border-radius: 50%; display: grid; place-items: center; }
.avatar-btn:hover { background: var(--hover); }
.avatar {
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #fff;
  font-weight: 500;
  flex: none;
  letter-spacing: 0.2px;
}
.top-actions { display: flex; align-items: center; gap: 2px; }

.search {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  height: 46px;
  max-width: 720px;
  width: 100%;
  background: var(--search);
  border-radius: 24px;
  padding: 0 8px 0 14px;
  color: var(--icon);
}
.search.focus { background: var(--surface); box-shadow: var(--pop); }
.search input { flex: 1; min-width: 0; height: 100%; outline: none; }
.search-spacer { flex: 1; }
.suggest {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  background: var(--surface);
  box-shadow: var(--pop);
  border-radius: 8px;
  z-index: 30;
  padding: 6px 0;
  max-height: 360px;
  overflow: auto;
}
.suggest button, .menu-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  text-align: left;
  padding: 8px 16px;
  min-height: 36px;
  color: var(--text);
}
.suggest button:hover, .menu-item:hover { background: var(--hover); }
.suggest button small, .menu-item small, .menu-note { color: var(--muted); font-size: 12px; }
.suggest-ops { display: flex; flex-wrap: wrap; gap: 6px; padding: 8px 12px 10px; }
.suggest-ops button {
  width: auto;
  border-radius: 12px;
  background: var(--search);
  padding: 4px 8px;
  font-size: 12px;
}
.advanced {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  width: min(420px, 90vw);
  background: var(--surface);
  box-shadow: var(--pop);
  border-radius: 12px;
  padding: 16px;
  z-index: 32;
  display: grid;
  gap: 10px;
