:root {
  color-scheme: light;
  --bg: #f6f8fc;
  --surface: #ffffff;
  --text: #1f1f1f;
  --secondary: #444746;
  --muted: #5f6368;
  --icon: #444746;
  --hover: rgba(68, 71, 70, 0.08);
  --nav-active: #d3e3fd;
  --nav-text: #041e49;
  --compose: #c2e7ff;
  --compose-text: #001d35;
  --search: #e9eef6;
  --blue: #0b57d0;
  --row-read: #f2f6fc;
  --row-unread: #ffffff;
  --row-hover: #e8f0fe;
  --row-selected: #c2e7ff;
  --line: #e1e3e1;
  --danger: #b3261e;
