.attach strong { font-size: 13px; font-weight: 500; }
.reply-launch { display: flex; gap: 8px; padding: 16px 0 8px; flex-wrap: wrap; }
.reply-launch button {
  height: 36px;
  padding: 0 16px;
  border-radius: 18px;
  border: 1px solid var(--line);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--secondary);
}
.reply-launch button:hover { background: var(--hover); }

.compose.float {
  position: fixed;
  bottom: 0;
  width: min(560px, calc(100vw - 32px));
  height: min(520px, calc(100dvh - 80px));
  background: var(--surface);
  border-radius: 8px 8px 0 0;
  box-shadow: var(--shadow);
  z-index: 45;
  display: flex;
  flex-direction: column;
}
.compose.float.min { height: 40px; width: 264px; }
.compose.float.max { top: 24px; left: 80px; right: 16px; width: auto; height: auto; bottom: 0; }
.compose.inline {
  border: 1px solid var(--line);
  border-radius: 12px;
  margin: 12px 0 24px 52px;
  display: flex;
  flex-direction: column;
  min-height: 280px;
  background: var(--surface);
}
.compose.drag { outline: 2px dashed var(--blue); }
.compose-head {
  height: 40px;
  background: var(--head);
  border-radius: 8px 8px 0 0;
  display: flex;
  align-items: center;
  padding: 0 4px 0 12px;
  flex: none;
}
.compose.inline .compose-head { border-radius: 12px 12px 0 0; }
.head-title { flex: 1; text-align: left; font-weight: 500; font-size: 14px; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.compose-fields { flex: none; }
.recipient-row, .subject-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  border-bottom: 1px solid var(--line);
  padding: 2px 12px;
  position: relative;
}
.recipient-row > span { width: 28px; color: var(--muted); font-size: 13px; }
.recipient-box { flex: 1; display: flex; flex-wrap: wrap; gap: 4px; align-items: center; min-width: 0; position: relative; }
.recipient-box input { flex: 1; min-width: 80px; height: 28px; outline: none; }
.person-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 24px;
  padding: 0 6px 0 2px;
  border-radius: 12px;
  background: var(--search);
  font-size: 13px;
}
.person-chip button { display: grid; color: var(--muted); }
.cc-links { display: flex; gap: 8px; color: var(--muted); font-size: 13px; flex: none; white-space: nowrap; }
.subject-row input { width: 100%; height: 32px; outline: none; }
.editor {
  flex: 1;
  min-height: 160px;
  overflow: auto;
  padding: 12px 16px;
  outline: none;
  font-size: 14px;
  line-height: 1.5;
}
.editor .sig { color: var(--muted); margin-top: 12px; }
.compose-files { padding: 0 12px 8px; }
.compose-error, .compose-confirm {
  margin: 0 12px 8px;
  color: var(--danger);
  font-size: 13px;
}
.compose-confirm { display: flex; gap: 8px; align-items: center; color: var(--text); }
.compose-bar {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 12px 12px;
  position: relative;
  flex: none;
}
.send-split { display: flex; gap: 2px; position: relative; }
.send-btn, .send-caret, .danger-btn {
  height: 36px;
  border-radius: 18px;
  background: #0b57d0;
  color: white;
  padding: 0 16px;
  font-weight: 500;
}
:root[data-theme="dark"] .send-btn, :root[data-theme="dark"] .send-caret { background: #a8c7fa; color: #062e6f; }
.send-caret { width: 32px; padding: 0; display: grid; place-items: center; }
.send-btn:disabled { opacity: 0.5; }
.danger-btn { background: var(--danger); }
.format-bar { display: flex; align-items: center; position: relative; }
.format-bar button { width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; color: var(--icon); }
.format-bar button:hover { background: var(--hover); }
.link-pop, .schedule-menu {
  position: absolute;
  bottom: 46px;
  left: 0;
  background: var(--surface);
  box-shadow: var(--pop);
  border-radius: 8px;
  padding: 8px;
  z-index: 2;
  display: flex;
  gap: 6px;
}
.schedule-menu { display: block; min-width: 220px; padding: 6px 0; }
.link-pop input { border: 1px solid var(--line); border-radius: 6px; padding: 6px 8px; }
.recipient-suggest { top: 100%; left: 0; right: auto; width: min(360px, 70vw); }
.recipient-suggest button { align-items: center; }
.recipient-suggest strong, .recipient-suggest small { display: block; }

.menu, .palette, .quick, .account-menu {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  min-width: 220px;
  background: var(--surface);
  box-shadow: var(--pop);
  border-radius: 8px;
  z-index: 40;
  padding: 6px 0;
}
.menu.align-right, .quick, .account-menu { left: auto; right: 0; }
.palette { position: fixed; z-index: 60; max-height: 70vh; overflow: auto; }
.menu-item.stack { flex-direction: column; align-items: flex-start; gap: 0; }
.menu-item:disabled { opacity: 0.45; }
.menu-empty, .menu-note { padding: 8px 16px; margin: 0; }
.menu-date { display: grid; gap: 6px; padding: 8px 16px 12px; font-size: 13px; }
.menu-date input { border: 1px solid var(--line); border-radius: 6px; padding: 6px; }
.quick { width: 300px; padding: 12px 16px 16px; }
.quick fieldset { border: 0; margin: 8px 0; padding: 0; display: grid; gap: 6px; }
.quick legend { font-size: 12px; color: var(--muted); margin-bottom: 4px; }
.quick label { display: flex; gap: 8px; align-items: center; text-transform: capitalize; font-size: 14px; }
.account-card { display: grid; justify-items: center; gap: 4px; padding: 12px 16px 8px; }
.account-card span { color: var(--muted); font-size: 13px; }
.text-btn { color: var(--blue); padding: 6px 8px; border-radius: 8px; white-space: nowrap; flex: none; }
.text-btn:hover { background: var(--hover); }
.text-btn.danger { color: var(--danger); }

.modal-back {
  position: fixed;
  inset: 0;
  background: rgba(32, 33, 36, 0.45);
  z-index: 70;
  display: grid;
  place-items: center;
  padding: 16px;
}
.modal {
  width: min(720px, 100%);
  max-height: min(80dvh, 720px);
  overflow: auto;
  background: var(--surface);
  border-radius: 16px;
  box-shadow: var(--shadow);
  padding: 8px 8px 16px;
}
.modal.narrow { width: min(420px, 100%); padding: 8px 16px 16px; }
.modal header, .settings-head { display: flex; align-items: center; justify-content: space-between; min-height: 48px; }
.modal p { color: var(--secondary); }
.modal-actions { display: flex; justify-content: flex-end; gap: 8px; align-items: center; }
.shortcut-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 24px; padding: 8px 16px 16px; }
.shortcut { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; border-bottom: 1px solid var(--line); font-size: 13px; }
kbd { font-family: var(--font); color: var(--muted); }
.preview pre { white-space: pre-wrap; background: var(--bg); border-radius: 8px; padding: 12px; margin: 8px 16px; max-height: 360px; overflow: auto; }
.preview img { max-width: 100%; border-radius: 8px; margin: 8px 16px; }
.swatches { display: flex; flex-wrap: wrap; gap: 8px; margin: 12px 0; }
.swatches button { width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; border: 2px solid transparent; }
.swatches button.on { border-color: var(--text); }

.snack {
  position: fixed;
  left: calc(var(--side) + 24px);
  bottom: 24px;
  background: var(--snack);
  color: white;
  min-height: 48px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 8px 0 16px;
  z-index: 80;
  box-shadow: var(--pop);
}
:root[data-theme="dark"] .snack { color: #1f1f1f; }
.snack button { color: #a8c7fa; font-weight: 500; height: 36px; padding: 0 12px; border-radius: 4px; }
:root[data-theme="dark"] .snack button { color: #062e6f; }

.settings-head { padding: 0 8px; border-bottom: 1px solid var(--line); }
.settings-body { overflow: auto; padding: 8px 24px 32px; }
.settings h2 { font-size: 16px; font-weight: 500; margin: 22px 0 10px; }
.setting-grid { display: grid; grid-template-columns: 140px minmax(0, 1fr); gap: 12px 16px; align-items: center; }
.choices { display: flex; flex-wrap: wrap; gap: 6px; }
.choices button { height: 32px; padding: 0 12px; border-radius: 16px; border: 1px solid var(--line); text-transform: capitalize; }
.choices button.on { background: var(--nav-active); color: var(--nav-text); border-color: transparent; }
.label-admin { list-style: none; padding: 0; margin: 0 0 8px; }
.label-admin li { display: flex; align-items: center; gap: 10px; height: 36px; }
.label-admin i { width: 12px; height: 12px; border-radius: 3px; }
.label-admin button { margin-left: auto; color: var(--blue); }

.gate {
  min-height: 100dvh;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 20px;
  background: var(--bg);
}
.account-pick {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--surface);
  border-radius: 16px;
  padding: 12px 18px;
  box-shadow: var(--pop);
  min-width: 280px;
  text-align: left;
}
.account-pick span { display: grid; }
.account-pick small { color: var(--muted); }
.fab {
  position: fixed;
  right: 16px;
  bottom: 16px;
  width: 56px;
  height: 56px;
  border-radius: 16px;
  background: var(--compose);
  box-shadow: var(--pop);
  z-index: 30;
}
.fab .pencil {
  width: 22px;
  height: 22px;
  display: block;
  margin: auto;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill='%23001d35' d='M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04a1 1 0 0 0 0-1.41l-2.34-2.34a1 1 0 0 0-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z'/></svg>") center / contain no-repeat;
}
.backdrop {
  position: fixed;
  inset: 0;
  background: rgba(32, 33, 36, 0.4);
  border: 0;
  z-index: 40;
}
.pop { position: relative; }
mark { background: #fde293; color: #1f1f1f; border-radius: 2px; }

@media (max-width: 900px) {
  .app { --side: 0px; }
  .snack { left: 12px; right: 12px; top: 68px; bottom: auto; }
  .list-pane { padding-bottom: 88px; }
  .topbar { grid-template-columns: auto minmax(0, 1fr) auto; }
  .body { grid-template-columns: 1fr; }
  .sidebar {
    position: fixed;
    z-index: 50;
    top: 0;
    bottom: 0;
    left: 0;
    width: min(300px, 88vw);
    background: var(--bg);
    transform: translateX(-105%);
    transition: transform 0.18s ease;
    box-shadow: none;
  }
  .sidebar.is-open { transform: none; box-shadow: var(--shadow); }
  .mail { margin: 0; border-radius: 0; }
  .hide-xs { display: none; }
  .logo { font-size: 18px; }
}
@media (max-width: 720px) {
  .row {
    height: auto;
    min-height: 72px;
    grid-template-columns: 24px 24px minmax(0, 1fr) auto;
    grid-template-areas: "check star sender when" "check star content content";
    padding: 8px 8px 8px 4px;
    align-items: start;
  }
  .imp { display: none; }
  .sender { grid-area: sender; }
  .content { grid-area: content; display: block; }
  .content .snippet { display: block; margin-left: 0; }
  .when { grid-area: when; }
  .row:hover .when { visibility: visible; }
  .row-actions { display: none !important; }
  .check-hit { grid-area: check; }
  .star { grid-area: star; }
  .compose.float, .compose.float.max, .compose.float.min {
    inset: 0;
    width: 100%;
    height: 100%;
    max-height: none;
    border-radius: 0;
  }
  .compose.inline { margin-left: 0; }
  .msg-body, .attach-row { padding-left: 0; }
  .thread-scroll { padding: 8px 12px 24px; }
  .setting-grid, .shortcut-grid { grid-template-columns: 1fr; }
  .tab { min-width: 96px; flex: 0 0 auto; padding: 0 12px; }
  .tab span { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

