:root {
  color-scheme: light;
  --bg: #f6f8fc;
  --surface: #ffffff;
  --text: #1f1f1f;
  --secondary: #444746;
  --muted: #5f6368;
  --icon: #444746;
  --hover: rgba(68, 71, 70, 0.08);
  --nav-active: #d3e3fd;
  --nav-text: #041e49;
  --compose: #c2e7ff;
  --compose-text: #001d35;
  --search: #e9eef6;
  --blue: #0b57d0;
  --row-read: #f2f6fc;
  --row-unread: #ffffff;
  --row-hover: #e8f0fe;
  --row-selected: #c2e7ff;
  --line: #e1e3e1;
  --danger: #b3261e;
  --draft: #d93025;
  --star: #f9ab00;
  --important: #f9ab00;
  --snack: #303134;
  --logo: #5f6368;
  --shadow: 0 8px 10px 1px rgba(0, 0, 0, 0.14), 0 3px 14px 2px rgba(0, 0, 0, 0.12);
  --pop: 0 1px 2px rgba(60, 64, 67, 0.3), 0 2px 6px 2px rgba(60, 64, 67, 0.15);
  --head: #f2f6fc;
  --quote: #dadce0;
  --side: 256px;
  --top: 64px;
  --font: Roboto, "Segoe UI", Helvetica, Arial, sans-serif;
  --row-h: 40px;
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #131314;
  --surface: #1f1f1f;
  --text: #e3e3e3;
  --secondary: #c4c7c5;
  --muted: #9aa0a6;
  --icon: #c4c7c5;
  --hover: rgba(255, 255, 255, 0.08);
  --nav-active: #004a77;
  --nav-text: #c2e7ff;
  --compose: #a8c7fa;
  --compose-text: #062e6f;
  --search: #282a2c;
  --blue: #a8c7fa;
  --row-read: #1a1c1e;
  --row-unread: #26282c;
  --row-hover: #2f3236;
  --row-selected: #004a77;
  --line: #3c4043;
  --danger: #f2b8b5;
  --draft: #f2b8b5;
  --snack: #e3e3e3;
  --logo: #e3e3e3;
  --head: #2d2f31;
  --quote: #5f6368;
  --shadow: 0 8px 16px rgba(0, 0, 0, 0.45);
  --pop: 0 4px 16px rgba(0, 0, 0, 0.45);
}

* { box-sizing: border-box; }
html, body, #root { height: 100%; }
body {
  margin: 0;
  overflow: hidden;
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}
button, input, textarea { font: inherit; color: inherit; }
button { background: none; border: 0; padding: 0; cursor: pointer; }
input, textarea { background: transparent; border: 0; }
a { color: var(--blue); }
:focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; }
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.app {
  height: 100dvh;
  display: grid;
  grid-template-rows: var(--top) minmax(0, 1fr);
  background: var(--bg);
}
.app[data-collapsed="true"] { --side: 72px; }
.app[data-density="compact"] { --row-h: 32px; }
.app[data-density="comfortable"] { --row-h: 52px; }

.topbar {
  display: grid;
  grid-template-columns: var(--side) minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding-right: 12px;
  height: var(--top);
}
.brand { display: flex; align-items: center; gap: 4px; padding-left: 8px; min-width: 0; }
.logo {
  margin: 0;
  font-size: 22px;
  font-weight: 400;
  letter-spacing: -0.2px;
  color: var(--logo);
  white-space: nowrap;
  line-height: 1;
}
.icon-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--icon);
  flex: none;
}
.icon-btn:hover { background: var(--hover); }
.icon-btn.tiny { width: 28px; height: 28px; }
.icon-btn:disabled { opacity: 0.38; cursor: default; }
.avatar-btn { width: 48px; height: 48px; border-radius: 50%; display: grid; place-items: center; }
.avatar-btn:hover { background: var(--hover); }
.avatar {
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #fff;
  font-weight: 500;
  flex: none;
  letter-spacing: 0.2px;
}
.top-actions { display: flex; align-items: center; gap: 2px; }

.search {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  height: 46px;
  max-width: 720px;
  width: 100%;
  background: var(--search);
  border-radius: 24px;
  padding: 0 8px 0 14px;
  color: var(--icon);
}
.search.focus { background: var(--surface); box-shadow: var(--pop); }
.search input { flex: 1; min-width: 0; height: 100%; outline: none; }
.search-spacer { flex: 1; }
.suggest {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
