args.command:
PLAYWRIGHT_BROWSERS_PATH="$PWD/.playwright" node --input-type=module -e '
import { chromium } from "playwright";
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto("http://127.0.0.1:9353", { waitUntil: "domcontentloaded" });
await page.locator("[data-testid=compose-open]").click();
await page.waitForSelector("[data-testid=compose-window]");
const info = await page.evaluate(() => {
  const win = document.querySelector("[data-testid=compose-window]");
  const row = win.querySelector(".recipient-row");
  const fields = win.querySelector(".compose-fields");
  const cs = getComputedStyle(fields);
  return {
    win: win.getBoundingClientRect().width,
    fields: fields.getBoundingClientRect().width,
    row: row.getBoundingClientRect().width,
    fieldsMin: cs.minWidth,
    fieldsWidth: cs.width,
    fieldsFlex: cs.flex,
    overflow: fields.scrollWidth,
  };
});
console.log(info);
await browser.close();
'

