  const win = document.querySelector("[data-testid=compose-window]");
  const bcc = [...win.querySelectorAll("button")].find((b) => b.textContent.trim() === "Bcc");
  const w = win.getBoundingClientRect();
  const b = bcc.getBoundingClientRect();
  return { winRight: w.right, bccRight: b.right, overflow: win.scrollWidth - win.clientWidth };
});
console.log(info);
await browser.close();
'

