.modal-back {
  position: fixed;
  inset: 0;
  background: rgba(32, 33, 36, 0.45);
  z-index: 70;
  display: grid;
  place-items: center;
  padding: 16px;
}
.modal {
  width: min(720px, 100%);
  max-height: min(80dvh, 720px);
